let page='home', step=0, resultId=null, config={aiConfigured:false,locked:false}, busy=false, timer=null, recognition=null, recorder=null, stream=null, recordChunks=[],recordingStop=null, audioUrls=[],messageTimer=null, requestError='';
if(state.active) {state.active.paused=true;state.active.lastTick=Date.now();}
