function header() { return `<header><a class="brand" href="#" data-action="home"><img src="./jkspeak-mark.svg" alt=""><span>JKSpeak<small>ORAL EXAM</small></span></a><nav aria-label="Main">${[['home','Overview'],['history','Sessions'],['growth','Progress'],['settings','Settings']].map(([key,label])=>`<button data-action="${key}" ${page===key?'aria-current="page"':''} class="${page===key?'active':''}">${label}</button>`).join('')}</nav><div class="account-menu"><span class="status">${esc(identity.profile.displayName)}</span>${identity.guest?'<span class="caption">Local guest practice</span><a class="btn small" href="./login.html">Log in</a>':'<a class="btn small" href="./profile.html">Profile</a><button type="button" class="btn small" data-action="sign-out">Sign out</button>'}</div></header>`; }
